const ideas={marca:{number:'01',title:'Sua marca merece espaço.',text:'Combine cartões, adesivos e uma fachada com personalidade para criar uma presença que as pessoas reconheçam.',cta:'Vamos criar para minha marca',service:'Fachadas'},festa:{number:'02',title:'Um cenário para boas memórias.',text:'Displays personalizados e backdrops ajudam a dar o tom da sua celebração. Conte o tema, a data e o espaço que você tem em mente.',cta:'Vamos planejar minha festa',service:'Displays para festa'},presente:{number:'03',title:'O melhor detalhe é ser pessoal.',text:'Uma caneca, um copo ou uma lembrança com a sua ideia. Transforme nomes, frases e referências em um presente com significado.',cta:'Vamos personalizar meu presente',service:'Canecas e copos personalizados'}};let selectedIdea='marca';
