if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('entered');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-top,.about-art,.about-copy,.service,.extras,.more-services,.project,.play-section>div,.steps>div,.faq>div,.quote-section>div,.quote-section form,.contact>div,.idea-lab>h2,.idea-result').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--delay',(el.classList.contains('project')?i%3*70:0)+'ms');observer.observe(el)});document.body.classList.add('motion-ready')}
// Begin only after the browser has rendered a visible page.
let introTimer;let introFrame=0;
function playPrintIntro(){
 if(document.visibilityState==='hidden')return;
 clearTimeout(introTimer);cancelAnimationFrame(introFrame);
 document.documentElement.classList.remove('intro-enabled');
 introFrame=requestAnimationFrame(()=>{introFrame=requestAnimationFrame(()=>{
 document.documentElement.classList.add('intro-enabled');
 introTimer=setTimeout(()=>document.documentElement.classList.remove('intro-enabled'),2700);
 });});
}
function schedulePrintIntro(){if(document.visibilityState==='hidden'){document.addEventListener('visibilitychange',function visible(){if(document.visibilityState==='visible'){document.removeEventListener('visibilitychange',visible);playPrintIntro();}});}else playPrintIntro();}
if(document.readyState==='complete')schedulePrintIntro();else window.addEventListener('load',schedulePrintIntro,{once:true});
document.querySelector('.replay-intro').addEventListener('click',playPrintIntro);
window.addEventListener('pageshow',event=>{if(event.persisted)schedulePrintIntro()});
// Update only while the print story is on screen; scrolling remains native.
(()=>{const story=document.querySelector('.print-journey');if(!story)return;const chapters=[...story.querySelectorAll('[data-j-step]')],labels=['01 / O PRIMEIRO TRAÇO','02 / CAMADAS DE COR','03 / IMPRESSÃO E ACABAMENTO','04 / PRONTA PARA APARECER'];const controls=[...story.querySelectorAll('[data-j-go]')];controls.forEach(button=>button.addEventListener('click',()=>{const chapter=chapters[Number(button.dataset.jGo)],visual=story.querySelector('.journey-visual').getBoundingClientRect();const target=innerWidth<=720?Math.min(innerHeight-100,visual.height+132):innerHeight*.55;const r=chapter.getBoundingClientRect();window.scrollTo({top:scrollY+r.top+r.height/2-target,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}));let frame=0,visible=true;function update(){frame=0;if(!visible)return;const visual=story.querySelector('.journey-visual').getBoundingClientRect();const target=innerWidth<=720?Math.min(innerHeight-100,visual.bottom+120):innerHeight*.55;let current=0,distance=Infinity;chapters.forEach((chapter,i)=>{const r=chapter.getBoundingClientRect(),d=Math.abs(r.top+r.height/2-target);if(d<distance){distance=d;current=i}});if(story.dataset.stage!==String(current)){story.dataset.stage=current;controls.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===current)));document.getElementById('journey-stage-label').textContent=labels[current];chapters.forEach((chapter,i)=>chapter.classList.toggle('is-current',i===current))}}function schedule(){if(visible&&!frame)frame=requestAnimationFrame(update)}if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)schedule()},{rootMargin:'100px'}).observe(story);addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});schedule()})();
// One collection, four personalities, with color becoming printed pieces.
(()=>{const studio=document.querySelector('.mood-studio');if(!studio)return;const moods={elegante:{edition:'01',poster:['MENOS.','MELHOR.'],line:'PRESENÇA NOS DETALHES.',card:['prazer,','essência.'],sticker:['BEM','FEITO.'],description:'Tons suaves, espaço e letras refinadas para uma presença elegante.'},divertido:{edition:'02',poster:['SAIA DO','ÓBVIO.'],line:'COR PARA QUEM NÃO PASSA DESPERCEBIDO.',card:['olá,','possibilidades.'],sticker:['SEU','JEITO.'],description:'Formas livres, contraste e energia para uma ideia cheia de personalidade.'},corporativo:{edition:'03',poster:['PRESENÇA.','CONFIANÇA.'],line:'CLAREZA PARA CONECTAR SUA MARCA.',card:['conexões','que ficam.'],sticker:['SUA','MARCA.'],description:'Linhas definidas e uma composição clara para comunicar com confiança.'},festivo:{edition:'04',poster:['HOJE É','SEU DIA.'],line:'MOMENTOS GRANDES MERECEM MAIS COR.',card:['vamos','celebrar.'],sticker:['MAIS','FESTA.'],description:'Cores vibrantes e formas de celebração para transformar uma ocasião em memória.'}};let selected='divertido',restart;const buttons=[...studio.querySelectorAll('[data-mood-choice]')];function lines(id,values){document.getElementById(id).replaceChildren(document.createTextNode(values[0]),document.createElement('br'),document.createTextNode(values[1]))}function animate(){studio.classList.remove('mood-enter');cancelAnimationFrame(restart);restart=requestAnimationFrame(()=>{restart=requestAnimationFrame(()=>studio.classList.add('mood-enter'))})}buttons.forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.moodChoice;const mood=moods[selected];studio.dataset.mood=selected;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));lines('mood-poster-text',mood.poster);lines('mood-card-text',mood.card);lines('mood-sticker-text',mood.sticker);document.getElementById('mood-edition').textContent=mood.edition;document.getElementById('mood-poster-line').textContent=mood.line;document.getElementById('mood-description').textContent=mood.description;animate()}));document.getElementById('mood-request').addEventListener('click',()=>{const details=document.getElementById('details');const note='Gostei da vitrine no estilo '+selected+' e quero conversar sobre uma coleção personalizada.';if(!details.value.includes(note))details.value=(details.value.trim()?details.value.trim()+'\n':'')+note;document.getElementById('orcamento').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){animate();observer.disconnect()}},{threshold:.2});observer.observe(studio)}})();
// A print registration ring follows a precise custom pointer on desktops only.
(()=>{const enabled=matchMedia('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)');const ring=document.createElement('div');ring.className='print-cursor';ring.setAttribute('aria-hidden','true');ring.innerHTML='<span></span>';document.body.append(ring);let frame=0,x=0,y=0;document.addEventListener('pointermove',event=>{if(!enabled.matches||event.pointerType==='touch'){ring.style.opacity='0';return}x=event.clientX;y=event.clientY;ring.style.opacity='1';ring.classList.toggle('is-link',!!event.target.closest('a,button,summary,select'));if(!frame)frame=requestAnimationFrame(()=>{ring.style.transform='translate3d('+(x-17)+'px,'+(y-17)+'px,0)';frame=0})},{passive:true});document.documentElement.addEventListener('pointerleave',()=>ring.style.opacity='0');document.addEventListener('pointerdown',()=>ring.classList.add('is-down'));document.addEventListener('pointerup',()=>ring.classList.remove('is-down'));document.addEventListener('keydown',()=>ring.style.opacity='0');window.addEventListener('blur',()=>ring.style.opacity='0')})();
// Fold the sticker across x+y=c; mouse, touch and keyboard share one control.
(()=>{const button=document.getElementById('peel-sticker');if(!button)return;const front=document.getElementById('peel-front-shape'),fold=document.getElementById('peel-fold'),reset=document.getElementById('peel-reset'),status=document.getElementById('peel-status');let value=.16,animation=0,drag=null,suppress=false;function draw(v){value=v;const c=2-v;let points,a,b;if(c>=1){points=[[0,0],[1,0],[1,c-1],[c-1,1],[0,1]];a=[1,c-1];b=[c-1,1]}else{const n=Math.max(0,c);points=[[0,0],[n,0],[0,n]];a=[n,0];b=[0,n]}const encode=list=>list.map(p=>p.map(n=>Math.round(n*500)).join(',')).join(' ');front.setAttribute('points',encode(points));fold.setAttribute('points',encode([a,b,[c-1,c-1]]));fold.style.opacity=v>=2?'0':'1'}function finish(open){cancelAnimationFrame(animation);const start=value,end=open?2.03:.16,at=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:700;function tick(now){const p=duration?Math.min(1,(now-at)/duration):1;draw(start+(end-start)*(1-Math.pow(1-p,3)));if(p<1)animation=requestAnimationFrame(tick);else{button.classList.toggle('is-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Mensagem revelada':'Descolar o adesivo e revelar a mensagem');reset.hidden=!open;status.textContent=open?'Sua ideia já tem um próximo passo.':'Uma surpresa debaixo da cor.';if(open&&document.activeElement===button)reset.focus({preventScroll:true})}}animation=requestAnimationFrame(tick)}button.addEventListener('pointerdown',e=>{if(e.button!==0)return;cancelAnimationFrame(animation);drag={id:e.pointerId,x:e.clientX,start:value,width:button.getBoundingClientRect().width};suppress=false;button.setPointerCapture(e.pointerId)});button.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const delta=(drag.x-e.clientX)/drag.width;if(Math.abs(delta)>.025)suppress=true;draw(Math.max(.05,Math.min(2.03,drag.start+delta*2)))});button.addEventListener('pointerup',()=>{if(!drag)return;drag=null;if(suppress)finish(value>.65)});button.addEventListener('pointercancel',()=>{drag=null;suppress=true;finish(false)});button.addEventListener('click',()=>{if(suppress){suppress=false;return}finish(true)});reset.addEventListener('click',()=>{button.classList.remove('is-open');finish(false);button.focus({preventScroll:true})});draw(.16)})();

// Keep the compact navigation state consistent across orientation changes.
function closeCompactNav(){mainNav.classList.remove('open');menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Abrir menu')}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mainNav.classList.contains('open')){closeCompactNav();menuToggle.focus()}});matchMedia('(min-width:1001px)').addEventListener('change',event=>{if(event.matches)closeCompactNav()});
